node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get the compatible products
const compatIds = ['PROD-B98D14','PROD-FA0948','PROD-2DBA15','PROD-7C0240'];
const placeholders = compatIds.map(() => '?').join(',');
const compatProducts = db.prepare('SELECT product_id, name FROM products WHERE product_id IN (' + placeholders + ')').all(...compatIds);
console.log('Compatible products:');
compatProducts.forEach(p => console.log('  ', p.product_id, '-', p.name));

// Also search for any product with 'Wireless Mouse' in the name
const mice = db.prepare(\"SELECT product_id, name FROM products WHERE name LIKE '%Wireless Mouse%'\").all();
console.log('\nProducts matching Wireless Mouse:');
mice.forEach(p => console.log('  ', p.product_id, '-', p.name));
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Full product details
const prod = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('=== FULL PRODUCT RECORD ===');
console.log(JSON.stringify(prod, null, 2));

// Check rt_variants table for this product
const variantCols = db.prepare(\"PRAGMA table_info('rt_variants')\").all();
console.log('\n=== rt_variants columns ===');
console.log(variantCols.map(c => c.name));

const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-73FAB4'\").all();
console.log('\n=== VARIANTS ===');
console.log(JSON.stringify(variants, null, 2));

// Resolve compatible product names
const compatIds = JSON.parse(prod.compatible_with_json);
if (compatIds.length) {
  const placeholders = compatIds.map(() => '?').join(',');
  const compatProducts = db.prepare('SELECT product_id, name FROM products WHERE product_id IN (' + placeholders + ')').all(...compatIds);
  console.log('\n=== COMPATIBLE PRODUCTS ===');
  console.log(JSON.stringify(compatProducts, null, 2));
}
"
